describe('Modal Full-Screen on Mobile Viewports', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
  });

  it('should display modal as full-screen on small mobile viewport', () => {
    cy.viewport('iphone-x');
    cy.get('[data-testid="open-modal-btn"]').click();
    cy.get('[data-testid="modal"]').should('be.visible');
    cy.get('[data-testid="modal"]').should('have.css', 'width', '100vw');
    cy.get('[data-testid="modal"]').should('have.css', 'height', '100vh');
    cy.get('[data-testid="modal"]').should('have.css', 'position', 'fixed');
    cy.get('[data-testid="modal"]').should('have.css', 'top', '0px');
    cy.get('[data-testid="modal"]').should('have.css', 'left', '0px');
  });

  it('should display modal as full-screen on small tablet viewport', () => {
    cy.viewport('ipad-mini');
    cy.get('[data-testid="open-modal-btn"]').click();
    cy.get('[data-testid="modal"]').should('be.visible');
    cy.get('[data-testid="modal"]').should('have.css', 'width', '100vw');
    cy.get('[data-testid="modal"]').should('have.css', 'height', '100vh');
  });

  it('should allow closing full-screen modal on mobile', () => {
    cy.viewport('iphone-x');
    cy.get('[data-testid="open-modal-btn"]').click();
    cy.get('[data-testid="modal"]').should('be.visible');
    cy.get('[data-testid="modal-close-btn"]').click();
    cy.get('[data-testid="modal"]').should('not.be.visible');
  });

  it('should display modal with constrained width on desktop viewport', () => {
    cy.viewport(1920, 1080);
    cy.get('[data-testid="open-modal-btn"]').click();
    cy.get('[data-testid="modal"]').should('be.visible');
    cy.get('[data-testid="modal"]').should('not.have.css', 'width', '100vw');
    cy.get('[data-testid="modal"]').invoke('width').should('be.lessThan', 1920);
  });

  it('should maintain full-screen modal on orientation change', () => {
    cy.viewport('iphone-x');
    cy.get('[data-testid="open-modal-btn"]').click();
    cy.get('[data-testid="modal"]').should('be.visible');
    cy.viewport('iphone-x', 'landscape');
    cy.get('[data-testid="modal"]').should('be.visible');
    cy.get('[data-testid="modal"]').should('have.css', 'width', '100vw');
  });

  it('should handle modal content overflow on small viewport', () => {
    cy.viewport('iphone-x');
    cy.get('[data-testid="open-modal-btn"]').click();
    cy.get('[data-testid="modal-content"]').should('be.visible');
    cy.get('[data-testid="modal-content"]').should('have.css', 'overflow-y', 'auto');
    cy.get('[data-testid="modal-content"]').should('have.css', 'max-height');
  });
});
